<?php
defined('ABSPATH')||exit;
add_filter('woocommerce_account_menu_items',function($items){$labels=['dashboard'=>'Dashboard','orders'=>'Orders','downloads'=>'Downloads','edit-address'=>'Addresses','edit-account'=>'Account Details','customer-logout'=>'Log Out'];foreach($items as $k=>$v)$items[$k]=$labels[$k]??$v;return $items;});
add_filter('gettext',function($translated,$text,$domain){if(is_admin()||!in_array($domain,['woocommerce','default'],true))return $translated;$map=['Home'=>'Home','Cart'=>'Cart','Checkout'=>'Checkout','My account'=>'My Account','Description'=>'Description','Additional information'=>'Additional information','Reviews'=>'Reviews','Choose an option'=>'Select Size','Clear'=>'Clear selection','Quantity'=>'Quantity','Out of stock'=>'Out of Stock','Your cart is currently empty.'=>'Your cart is empty.','Return to shop'=>'Continue Shopping','No products were found matching your selection.'=>'No products match your selection. Try another search or clear your filters.','Product'=>'Product','Price'=>'Price','Subtotal'=>'Subtotal','Total'=>'Total','Shipping'=>'Shipping','Cart totals'=>'Order Summary','Proceed to checkout'=>'Proceed to Checkout','Update cart'=>'Update Cart','Coupon code'=>'Coupon code','Apply coupon'=>'Apply','Billing details'=>'Customer Details','Your order'=>'Your Order','Place order'=>'Place Order','First name'=>'First name','Last name'=>'Last name','Country / Region'=>'Country / Region','Street address'=>'Street address','Town / City'=>'Town / City','State / County'=>'State / County','Phone'=>'Phone','Email address'=>'Email','Username or email address'=>'Username or email address','Password'=>'Password','Log in'=>'Log In','Login'=>'Log In','Register'=>'Register','Remember me'=>'Remember me','Lost your password?'=>'Lost your password?','Orders'=>'Orders','Order'=>'Orders','Date'=>'Date','Status'=>'Status','Actions'=>'Actions','View'=>'View Details','Order details'=>'Order Details','Billing address'=>'Billing Address','Shipping address'=>'Shipping Address','No order has been made yet.'=>'You have no orders yet.','Browse products'=>'Explore products','Save changes'=>'Save Changes','Remove this item'=>'Remove this item','Free shipping'=>'Free shipping','Product Details'=>'Product Details','Product Information'=>'Product Information'];return $map[$text]??$translated;},100,3);
add_filter('woocommerce_get_related_product_cat_terms',function($ids){$allowed=['lifestyle','running','basketball','football','training','air-force-1','jordan','air-max','dunk','cortez','pegasus','vomero','revolution','metcon','mercurial'];return array_values(array_filter($ids,function($id)use($allowed){$t=get_term($id,'product_cat');return $t&&!is_wp_error($t)&&in_array($t->slug,$allowed,true);}));});
add_filter('woocommerce_get_related_product_tag_terms',fn()=>[]);
add_filter('gettext',function($translated,$text,$domain){return !is_admin()&&$domain==='woocommerce'&&$text==='Shipment'?'Shipping':$translated;},110,3);
add_filter('woocommerce_get_privacy_policy_text',function($text,$type){if(!get_option('paxig_ui_demo'))return $text;return $type==='checkout'?'This is a demonstration order. Do not make a real payment or enter real personal details.':'Use a demonstration account only. Do not enter real personal details.';},100,2);
add_filter('woocommerce_shipping_package_name',fn($name)=>'Shipping');
// Preserve original layout; these hooks only fix labels, demo notices and native context.
add_filter('woocommerce_product_single_add_to_cart_text',fn()=> 'Add to Cart',100);
add_filter('woocommerce_product_add_to_cart_text',fn($text,$product)=>$product->is_type('variable')?'Select Size':'Add to Cart',100,2);
add_filter('woocommerce_page_title',fn($title)=>is_shop()?'All Shoes':$title,100);
add_filter('woocommerce_catalog_orderby',fn()=>['menu_order'=>'Featured','popularity'=>'Popularity','rating'=>'Reviews','date'=>'Newest','price'=>'Price: Low to High','price-desc'=>'Price: High to Low'],100);
add_filter('ngettext',function($translation,$single,$plural,$number,$domain){if($domain==='woocommerce'&&str_starts_with($single,'Showing'))return str_contains($plural,'%3$d')?'Showing %1$d–%2$d of %3$d products':'Showing %1$d products';return $translation;},100,5);
add_filter('gettext',function($translated,$text,$domain){if(!is_admin()&&$domain==='woocommerce'){$labels=['Add a review'=>'Add a Review','There are no reviews yet.'=>'There are no reviews yet.','Your rating'=>'Your Rating','Your review'=>'Your Review','Submit'=>'Submit','Showing the single result'=>'Showing the single result'];return $labels[$text]??$translated;}return $translated;},120,3);
add_action('widgets_init',function(){register_sidebar(['name'=>'Recently Viewed Products','id'=>'paxig-recent','before_widget'=>'<section class="paxig-recent-native">','after_widget'=>'</section>','before_title'=>'<h2>','after_title'=>'</h2>']);});
add_action('woocommerce_after_single_product_summary',function(){if(is_active_sidebar('paxig-recent'))dynamic_sidebar('paxig-recent');},25);
function paxig_original_demo_notice(){if(get_option('paxig_ui_demo'))echo '<p class="paxig-notice demo-notice"><strong>Demo Store</strong><span>Products, prices and orders are demonstration data. Do not transfer money or make a real payment.</span></p>';}
add_action('woocommerce_before_checkout_form','paxig_original_demo_notice',5);
add_action('woocommerce_thankyou','paxig_original_demo_notice',5);
// Navigation assistance only; keep native empty notices and catalogue queries intact.
add_action('woocommerce_no_products_found',function(){echo '<p class="paxig-empty-action"><a class="button" href="'.esc_url(wc_get_page_permalink('shop')).'">Shop All Shoes</a></p>';},20);
// Curated demo collection replaces only the old sales-ranking filter in the separate demo DB.
if(get_option('paxig_ui_demo')){
 remove_action('pre_get_posts','paxig_shoes_filter_best_sellers');
 add_action('pre_get_posts',function($q){if(is_admin()||!$q->is_main_query()||!$q->is_post_type_archive('product'))return;if(($_GET['paxig_best_sellers']??'')==='1'){$tax=$q->get('tax_query');if(!is_array($tax))$tax=[];$tax[]=['taxonomy'=>'product_cat','field'=>'slug','terms'=>['best-sellers']];$q->set('tax_query',$tax);}if(isset($_GET['paxig_original_category'])&&is_string($_GET['paxig_original_category']))$q->set('post__in',[0]);});
}
